34	        }
35	        int farmAvailable = turbines.stream().mapToInt(Turbine::getAvailablePowerKw).sum();
36	        // 可实现下限：小风停机风险机组按其实际可用出力计（不能压减到比实际出力还低）。
37	        int achievableFloor = turbines.stream()
38	                .mapToInt(t -> Math.min(t.getAvailablePowerKw(), t.getTechnicalMinKw()))
39	                .sum();
40	
41	        if (farmTargetKw > farmAvailable) {
42	            throw new ApiBadRequestException(
43	                    "目标出力 " + farmTargetKw + " kW 高于全场可用出力 " + farmAvailable + " kW，无需限电");
44	        }
45	        if (farmTargetKw < achievableFloor) {
46	            throw new ApiBadRequestException(
47	                    "目标出力 " + farmTargetKw + " kW 低于全场可实现下限 " + achievableFloor + " kW");
48	        }
