56	        long[] curtail = new long[n];
57	        // 恰等目标：curtaillTotal=0，所有机组 curtail=0（不降机）。
58	        if (curtailTotal > 0) {
59	            long[] rawFloor = new long[n];
60	            long assigned = 0;
