62	                long headroom = Math.max(0,
63	                        (long) turbines.get(i).getAvailablePowerKw()
64	                                - turbines.get(i).getTechnicalMinKw());
65	                long share = headroomTotal == 0 ? 0 : curtailTotal * headroom / headroomTotal;
66	                rawFloor[i] = share;
67	                assigned += share;
68	            }
69	            long remainder = curtailTotal - assigned;
70	
71	            // 尾差归入可降空间最大机组（并列时取机组编码靠前）；装不下则依次填满次大机组。
72	            List<Integer> orderByHeadroom = new ArrayList<>();
73	            for (int i = 0; i < n; i++) {
74	                orderByHeadroom.add(i);
75	            }
76	            orderByHeadroom.sort(Comparator
77	                    .comparingLong((Integer i) -> -Math.max(0,
78	                            (long) turbines.get(i).getAvailablePowerKw()
79	                                    - turbines.get(i).getTechnicalMinKw()))
80	                    .thenComparing(i -> turbines.get(i).getTurbineCode()));
81	
82	            for (int i = 0; i < n; i++) {
83	                curtail[i] = rawFloor[i];
84	            }
85	            for (int idx : orderByHeadroom) {
86	                if (remainder == 0) {
87	                    break;
88	                }
89	                long headroom = Math.max(0,
90	                        (long) turbines.get(idx).getAvailablePowerKw()
91	                                - turbines.get(idx).getTechnicalMinKw());
92	                long canTake = Math.min(remainder, headroom - curtail[idx]);
93	                curtail[idx] += canTake;
94	                remainder -= canTake;
95	            }
96	            if (remainder != 0) {
97	                // 理论不可达：farmTarget>=可实现下限 已保证可降总额足够。
98	                throw new ApiBadRequestException("分摊失败：可降空间不足以压减到目标出力");
