1	package com.example.starter.repo;
2	
3	import java.sql.PreparedStatement;
4	import java.sql.Statement;
5	import java.sql.Timestamp;
6	import java.time.Instant;
7	import java.util.List;
8	
9	import org.springframework.dao.EmptyResultDataAccessException;
10	import org.springframework.jdbc.core.JdbcTemplate;
11	import org.springframework.jdbc.core.RowMapper;
12	import org.springframework.jdbc.support.GeneratedKeyHolder;
13	import org.springframework.jdbc.support.KeyHolder;
14	import org.springframework.stereotype.Repository;
15	
16	import com.example.starter.domain.AlertEvent;
17	import com.example.starter.domain.AlertType;
18	import com.example.starter.domain.Allocation;
19	import com.example.starter.domain.CurtailOrder;
20	import com.example.starter.domain.DispatchCycle;
21	import com.example.starter.domain.ExecutionReport;
22	import com.example.starter.domain.LateReportEvent;
23	import com.example.starter.domain.OrderStatus;
24	
25	/**
26	 * 限电指令聚合数据访问：指令、轮次、分摊、回报、告警、迟到事件。
27	 */
28	@Repository
29	public class DispatchRepository {
30	
31	    private final JdbcTemplate jdbc;
32	
33	    public DispatchRepository(JdbcTemplate jdbc) {
34	        this.jdbc = jdbc;
35	    }
36	
37	    private static final RowMapper<CurtailOrder> ORDER_MAPPER = (rs, n) -> {
38	        CurtailOrder o = new CurtailOrder();
39	        o.setId(rs.getLong("id"));
40	        o.setOrderNo(rs.getString("order_no"));
41	        o.setFarmCode(rs.getString("farm_code"));
42	        o.setRequestId(rs.getString("request_id"));
43	        o.setFingerprint(rs.getString("fingerprint"));
44	        o.setTargetPowerKw(rs.getInt("target_power_kw"));
45	        o.setStatus(OrderStatus.valueOf(rs.getString("status")));
46	        o.setCurrentCycleNo(rs.getInt("current_cycle_no"));
47	        long sup = rs.getLong("superseded_by_order_id");
48	        o.setSupersededByOrderId(rs.wasNull() ? null : sup);
49	        o.setReceivedAt(rs.getTimestamp("received_at").toInstant());
50	        Timestamp settled = rs.getTimestamp("settled_at");
51	        o.setSettledAt(settled == null ? null : settled.toInstant());
52	        return o;
53	    };
54	
55	    private static final RowMapper<DispatchCycle> CYCLE_MAPPER = (rs, n) -> {
56	        DispatchCycle c = new DispatchCycle();
57	        c.setId(rs.getLong("id"));
58	        c.setOrderId(rs.getLong("order_id"));
59	        c.setCycleNo(rs.getInt("cycle_no"));
60	        c.setDispatchedAt(rs.getTimestamp("dispatched_at").toInstant());
61	        c.setDueAt(rs.getTimestamp("due_at").toInstant());
62	        return c;
63	    };
64	
65	    private static final RowMapper<Allocation> ALLOCATION_MAPPER = (rs, n) -> {
66	        Allocation a = new Allocation();
67	        a.setId(rs.getLong("id"));
68	        a.setOrderId(rs.getLong("order_id"));
69	        a.setCycleNo(rs.getInt("cycle_no"));
70	        a.setTurbineId(rs.getLong("turbine_id"));
71	        a.setBaseAvailableKw(rs.getInt("base_available_kw"));
72	        a.setTargetPowerKw(rs.getInt("target_power_kw"));
73	        a.setCurtailKw(rs.getInt("curtail_kw"));
74	        return a;
75	    };
76	
77	    private static final RowMapper<ExecutionReport> REPORT_MAPPER = (rs, n) -> {
78	        ExecutionReport r = new ExecutionReport();
79	        r.setId(rs.getLong("id"));
80	        r.setRequestId(rs.getString("request_id"));
81	        r.setOrderId(rs.getLong("order_id"));
82	        r.setTurbineId(rs.getLong("turbine_id"));
83	        r.setMeasuredAt(rs.getTimestamp("measured_at").toInstant());
84	        r.setPowerKw(rs.getInt("power_kw"));
85	        r.setReceivedAt(rs.getTimestamp("received_at").toInstant());
86	        return r;
87	    };
88	
89	    private static final RowMapper<AlertEvent> ALERT_MAPPER = (rs, n) -> {
90	        AlertEvent a = new AlertEvent();
91	        a.setId(rs.getLong("id"));
92	        a.setOrderId(rs.getLong("order_id"));
93	        a.setCycleNo(rs.getInt("cycle_no"));
94	        a.setType(AlertType.valueOf(rs.getString("type")));
95	        a.setFiredAt(rs.getTimestamp("fired_at").toInstant());
96	        int actual = rs.getInt("farm_actual_kw");
97	        a.setFarmActualKw(rs.wasNull() ? null : actual);
98	        int reallocated = rs.getInt("reallocated_cycle_no");
99	        a.setReallocatedCycleNo(rs.wasNull() ? null : reallocated);
100	        return a;
101	    };
102	
103	    private static final RowMapper<LateReportEvent> LATE_MAPPER = (rs, n) -> {
104	        LateReportEvent e = new LateReportEvent();
105	        e.setId(rs.getLong("id"));
106	        e.setOrderId(rs.getLong("order_id"));
107	        e.setTurbineCode(rs.getString("turbine_code"));
108	        e.setMeasuredAt(rs.getTimestamp("measured_at").toInstant());
109	        int power = rs.getInt("power_kw");
110	        e.setPowerKw(rs.wasNull() ? null : power);
111	        e.setRequestId(rs.getString("request_id"));
112	        e.setRecordedAt(rs.getTimestamp("recorded_at").toInstant());
113	        return e;
114	    };
115	
116	    public long insertOrder(CurtailOrder order) {
117	        KeyHolder keyHolder = new GeneratedKeyHolder();
118	        jdbc.update(connection -> {
119	            PreparedStatement ps = connection.prepareStatement("""
120	                    INSERT INTO curtail_order
121	                        (order_no, farm_code, request_id, fingerprint, target_power_kw,
122	                         status, current_cycle_no, superseded_by_order_id, active_flag,
123	                         received_at, settled_at)
124	                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
125	                    """, Statement.RETURN_GENERATED_KEYS);
126	            ps.setString(1, order.getOrderNo());
127	            ps.setString(2, order.getFarmCode());
128	            ps.setString(3, order.getRequestId());
129	            ps.setString(4, order.getFingerprint());
130	            ps.setInt(5, order.getTargetPowerKw());
131	            ps.setString(6, order.getStatus().name());
132	            ps.setInt(7, order.getCurrentCycleNo());
133	            if (order.getSupersededByOrderId() == null) {
134	                ps.setNull(8, java.sql.Types.BIGINT);
135	            } else {
136	                ps.setLong(8, order.getSupersededByOrderId());
137	            }
138	            // 新指令一律先以非执行中（active_flag=NULL）插入，由服务在旧指令作废后显式置 Y，
139	            // 保证同一事务内不会出现两个执行中指令。
140	            ps.setNull(9, java.sql.Types.CHAR);
141	            ps.setTimestamp(10, Timestamp.from(order.getReceivedAt()));
142	            ps.setTimestamp(11, order.getSettledAt() == null ? null : Timestamp.from(order.getSettledAt()));
143	            return ps;
144	        }, keyHolder);
145	        Number key = keyHolder.getKey();
146	        long id = key == null ? 0L : key.longValue();
147	        order.setId(id);
148	        return id;
149	    }
150	
151	    public CurtailOrder findOrderById(long id) {
152	        try {
153	            return jdbc.queryForObject("SELECT * FROM curtail_order WHERE id = ?", ORDER_MAPPER, id);
154	        } catch (EmptyResultDataAccessException ex) {
155	            return null;
156	        }
157	    }
158	
159	    public CurtailOrder findOrderByRequestId(String requestId) {
160	        try {
161	            return jdbc.queryForObject(
162	                    "SELECT * FROM curtail_order WHERE request_id = ?", ORDER_MAPPER, requestId);
163	        } catch (EmptyResultDataAccessException ex) {
164	            return null;
165	        }
166	    }
167	
168	    public CurtailOrder findOrderByNo(String orderNo) {
169	        try {
170	            return jdbc.queryForObject(
171	                    "SELECT * FROM curtail_order WHERE order_no = ?", ORDER_MAPPER, orderNo);
172	        } catch (EmptyResultDataAccessException ex) {
173	            return null;
174	        }
175	    }
176	
177	    /** 查询风场当前执行中（active_flag=Y）指令；必须在持有 wind_farm 行锁的事务内调用。 */
178	    public CurtailOrder findActiveOrder(String farmCode) {
179	        try {
180	            return jdbc.queryForObject(
181	                    "SELECT * FROM curtail_order WHERE farm_code = ? AND active_flag = 'Y'",
182	                    ORDER_MAPPER, farmCode);
183	        } catch (EmptyResultDataAccessException ex) {
184	            return null;
185	        }
186	    }
187	
188	    public CurtailOrder findLatestOrder(String farmCode) {
189	        try {
190	            return jdbc.queryForObject(
191	                    "SELECT * FROM curtail_order WHERE farm_code = ? ORDER BY id DESC LIMIT 1",
192	                    ORDER_MAPPER, farmCode);
193	        } catch (EmptyResultDataAccessException ex) {
194	            return null;
195	        }
