                ps.setNull(5, java.sql.Types.INTEGER);
            } else {
                ps.setInt(5, alert.getFarmActualKw());
            }
            if (alert.getReallocatedCycleNo() == null) {
                ps.setNull(6, java.sql.Types.INTEGER);
