228	    void settleIsTerminalAndLateReportsRecorded() {
229	        OrderReceiveResponse order = dispatchService.receive(
230	                new OrderReceiveRequest("req-8", FARM, 5000));
231	
232	        SettleResponse s1 = dispatchService.settle(order.orderNo());
233	        assertThat(s1.status()).isEqualTo("SETTLED");
