62	        jdbc.update("DELETE FROM alert_event");
63	        jdbc.update("DELETE FROM execution_report");
64	        jdbc.update("DELETE FROM allocation");
65	        jdbc.update("DELETE FROM dispatch_cycle");
66	        jdbc.update("DELETE FROM curtail_order");
67	        jdbc.update("DELETE FROM idempotent_record");
68	        jdbc.update("DELETE FROM wind_turbine");
69	        jdbc.update("DELETE FROM wind_farm");
70	        Instant now = Instant.now();
71	        jdbc.update("INSERT INTO wind_farm(farm_code, farm_name, created_at) VALUES (?, ?, ?)",
72	                FARM, "REST 测试风电场", now);
73	        for (Seed s : SEEDS) {
