110	    @Test
111	    @DisplayName("HTTP 主流程：接收分摊→重放→409→回报恰超时告警重分摊→日结→迟到回报→详情复算")
112	    void fullLifecycleOverHttp() {
113	        // 1. 接收：全场可用 6000，目标 5000，压减 1000。
114	        Map<String, Object> order = post("/api/curtail/orders",
115	                Map.of("requestId", "http-1", "farmCode", FARM, "targetPowerKw", 5000));
116	        assertThat(order.get("status")).isEqualTo("DISPATCHED");
117	        assertThat(((Number) order.get("curtailedKw")).intValue()).isEqualTo(1000);
118	        int allocSum = ((List<Map<String, Object>>) order.get("allocations")).stream()
119	                .mapToInt(a -> ((Number) a.get("targetPowerKw")).intValue()).sum();
120	        assertThat(allocSum).isEqualTo(5000);
121	        String orderNo = (String) order.get("orderNo");
122	
123	        // 2. 同键同参重放：replayed=true，同一 orderId。
124	        Map<String, Object> replay = post("/api/curtail/orders",
125	                Map.of("requestId", "http-1", "farmCode", FARM, "targetPowerKw", 5000));
126	        assertThat(replay.get("replayed")).isEqualTo(true);
127	        assertThat(replay.get("orderId")).isEqualTo(order.get("orderId"));
128	
129	        // 3. 同键异参：409。
130	        ResponseEntity<Map> conflict = postEntity("/api/curtail/orders",
131	                Map.of("requestId", "http-1", "farmCode", FARM, "targetPowerKw", 4999));
132	        assertThat(conflict.getStatusCode()).isEqualTo(HttpStatus.CONFLICT);
