public record OrderDetailResponse(
        Long orderId,
        String orderNo,
        String farmCode,
        String requestId,
        int targetPowerKw,
        String status,
        int currentCycleNo,
        Instant receivedAt,
        Instant settledAt,
        List<CycleView> cycles,
        List<ReportPoint> executionCurve,
        List<AlertView> alerts,
