        int segmentIndex,
        Instant segmentStart,
        Instant segmentEnd,
        boolean versionCurrent,
        List<CycleBasisView> cycles) {

    /** 一轮的冻结基数：计划值不可变（各轮一致），实时值为该轮时刻值，参与出力取两者较小者。 */
